function createBarMagnet() {
  const group = new THREE.Group();
  const width = 0.8;
  const height = 0.5;
  const depth = 2.4;

  const northGeo = new THREE.BoxGeometry(width, height, depth/2);
  const northMat = new THREE.MeshPhysicalMaterial({
    color: 0xd92b2b,
    metalness: 0.3,
    roughness: 0.2,
    clearcoat: 0.6,
    clearcoatRoughness: 0.2
  });
  const north = new THREE.Mesh(northGeo, northMat);
  north.position.z = -depth/4;
  north.castShadow = true;
  north.receiveShadow = true;

  const southGeo = new THREE.BoxGeometry(width, height, depth/2);
  const southMat = new THREE.MeshPhysicalMaterial({
    color: 0x2b5fd9,
    metalness: 0.3,
    roughness: 0.2,
    clearcoat: 0.6,
    clearcoatRoughness: 0.2
  });
  const south = new THREE.Mesh(southGeo, southMat);
  south.position.z = depth/4;
  south.castShadow = true;
  south.receiveShadow = true;

  const frameGeo = new THREE.BoxGeometry(width + 0.02, height + 0.02, depth + 0.02);
  const frameMat = new THREE.MeshStandardMaterial({
    color: 0xcccccc,
    metalness: 0.8,
    roughness: 0.2
  });
  const frame = new THREE.Mesh(frameGeo, frameMat);
  frame.castShadow = true;

  const poleGeo = new THREE.CylinderGeometry(0.15, 0.15, 0.02, 32);
  const poleNMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
  const poleN = new THREE.Mesh(poleGeo, poleNMat);
  poleN.rotation.x = Math.PI/2;
  poleN.position.set(0, height/2 + 0.01, -depth/4);

  const poleSMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
  const poleS = new THREE.Mesh(poleGeo, poleSMat);
  poleS.rotation.x = Math.PI/2;
  poleS.position.set(0, height/2 + 0.01, depth/4);

  group.add(frame);
  group.add(north);
  group.add(south);
  group.add(poleN);
  group.add(poleS);

  return group;
}

