// Procedural texture generator using DataTexture (no canvas needed)
function createIndustrialTexture(baseColorHex, noiseIntensity = 20) {
  const size = 256;
  const data = new Uint8Array(size * size * 4);
  const baseColor = new THREE.Color(baseColorHex);

  for (let i = 0; i < size * size; i++) {
    const i4 = i * 4;
    const noise = (Math.random() - 0.5) * noiseIntensity / 255;
    data[i4] = Math.max(0, Math.min(255, (baseColor.r + noise) * 255));
    data[i4 + 1] = Math.max(0, Math.min(255, (baseColor.g + noise) * 255));
    data[i4 + 2] = Math.max(0, Math.min(255, (baseColor.b + noise) * 255));
    data[i4 + 3] = 255;
  }

  const tex = new THREE.DataTexture(data, size, size, THREE.RGBAFormat);
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  tex.needsUpdate = true;
  return tex;
}

