// Enemies
const enemies = [];
function createEnemy(x, z) {
  const group = new THREE.Group();
  const body = new THREE.Mesh(new THREE.IcosahedronGeometry(0.5, 1), enemyMat);
  body.position.y = 0.5;
  body.castShadow = true;
  const eyeL = new THREE.Mesh(new THREE.SphereGeometry(0.08), new THREE.MeshBasicMaterial({ color: 0xffff00 }));
  eyeL.position.set(-0.15, 0.6, 0.35);
  const eyeR = eyeL.clone();
  eyeR.position.set(0.15, 0.6, 0.35);
  const spike = new THREE.Mesh(new THREE.ConeGeometry(0.1, 0.4), enemyMat);
  spike.position.set(0, 0.8, 0);
  group.add(body, eyeL, eyeR, spike);
  group.position.set(x, 0, z);
  group.userData = { hp: 3, dead: false, initialY: 0, bobOffset: Math.random() * Math.PI };
  scene.add(group);
  enemies.push(group);
}
createEnemy(7, 7);
createEnemy(-7, -7);
createEnemy(7, -7);

// Particles (blood)
const particles = [];
function createBlood(position) {
  for (let i = 0; i < 8; i++) {
    const mesh = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.08, 0.08), new THREE.MeshBasicMaterial({ color: 0x880000 }));
    mesh.position.copy(position);
    mesh.position.x += (Math.random() - 0.5) * 0.5;
    mesh.position.y += (Math.random() - 0.5) * 0.5;
    mesh.position.z += (Math.random() - 0.5) * 0.5;
    mesh.userData = {
      vel: new THREE.Vector3((Math.random()-0.5)*0.1, Math.random()*0.1, (Math.random()-0.5)*0.1),
      life: 1.0
    };
    scene.add(mesh);
    particles.push(mesh);
  }
}

// Controls
const keys = { w: false, a: false, s: false, d: false };
const playerVel = new THREE.Vector3();
const playerPos = new THREE.Vector3(0, 1.7, 8);
camera.position.copy(playerPos);
const euler = new THREE.Euler(0, 0, 0, 'YXZ');
let isLocked = false;

document.addEventListener('keydown', e => {
  const k = e.key.toLowerCase();
  if (keys.hasOwnProperty(k)) keys[k] = true;
});
document.addEventListener('keyup', e => {
  const k = e.key.toLowerCase();
  if (keys.hasOwnProperty(k)) keys[k] = false;
});
document.addEventListener('click', () => document.body.requestPointerLock());
document.addEventListener('pointerlockchange', () => isLocked = document.pointerLockElement === document.body);
document.addEventListener('mousemove', e => {
  if (!isLocked) return;
  euler.y -= e.movementX * 0.002;
  euler.x -= e.movementY * 0.002;
  euler.x = Math.max(-Math.PI/2.2, Math.min(Math.PI/2.2, euler.x));
  camera.quaternion.setFromEuler(euler);
});

// Shooting
const raycaster = new THREE.Raycaster();
document.addEventListener('mousedown', () => {
  if (!isLocked) return;
  // Recoil
  gunGroup.position.z += 0.15;
  gunGroup.rotation.x += 0.2;
  setTimeout(() => {
    gunGroup.position.z -= 0.15;
    gunGroup.rotation.x -= 0.2;
  }, 80);

  // Muzzle flash
  flashLight.intensity = 6;
  setTimeout(() => flashLight.intensity = 3, 50);

  // Hit detection
  raycaster.setFromCamera(new THREE.Vector2(0, 0), camera);
  const intersects = raycaster.intersectObjects(enemies, true);
  if (intersects.length > 0) {
    const hitObj = intersects[0].object.parent;
    if (hitObj.userData && !hitObj.userData.dead) {
      hitObj.userData.hp--;
      hitObj.scale.setScalar(0.8 + Math.random() * 0.2);
      setTimeout(() => hitObj.scale.setScalar(1), 100);
      if (hitObj.userData.hp <= 0) {
        hitObj.userData.dead = true;
        createBlood(hitObj.position);
        // Death animation
        const fall = () => {
          hitObj.rotation.x += 0.1;
          hitObj.position.y -= 0.05;
          if (hitObj.position.y > -0.5) requestAnimationFrame(fall);
          else hitObj.visible = false;
        };
        fall();
      }
    }
  }
});

// Collision detection
function checkCollision(pos) {
  const playerRadius = 0.4;
  for (const w of walls) {
    const minX = w.x - w.w/2 - playerRadius;
    const maxX = w.x + w.w/2 + playerRadius;
    const minZ = w.z - w.d/2 - playerRadius;
    const maxZ = w.z + w.d/2 + playerRadius;
    if (pos.x > minX && pos.x < maxX && pos.z > minZ && pos.z < maxZ) return true;
  }
  return pos.x < -11 || pos.x > 11 || pos.z < -11 || pos.z > 11;
}

function animate() {
  requestAnimationFrame(animate);
  const dt = clock.getDelta();
  const t = clock.getElapsedTime();

  // Movement
  const speed = 4 * dt;
  const dir = new THREE.Vector3();
  if (keys.w) dir.z -= 1;
  if (keys.s) dir.z += 1;
  if (keys.a) dir.x -= 1;
  if (keys.d) dir.x += 1;
  dir.normalize().applyQuaternion(camera.quaternion);
  dir.y = 0;

  const nextPos = camera.position.clone().add(dir.multiplyScalar(speed));
  if (!checkCollision(nextPos)) camera.position.copy(nextPos);
  camera.position.y = 1.7; // Keep head height

  // Gun sway
  gunGroup.position.x = 0.25 + Math.sin(t * 2) * 0.01;
  gunGroup.position.y = -0.2 + Math.cos(t * 1.5) * 0.01;

  // Enemy AI
  enemies.forEach(enemy => {
    if (enemy.userData.dead) return;
    // Bobbing
    enemy.position.y = enemy.userData.initialY + Math.sin(t * 3 + enemy.userData.bobOffset) * 0.05;
    // Face player
    enemy.lookAt(camera.position.x, enemy.position.y, camera.position.z);
  });

  // Particles
  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.position.add(p.userData.vel);
    p.userData.vel.y -= 0.005; // Gravity
    p.userData.life -= dt * 0.5;
    p.scale.setScalar(p.userData.life * 0.08);
    if (p.userData.life <= 0) {
      scene.remove(p);
      particles.splice(i, 1);
    }
  }

  // Pulsing lights
  hellLight.intensity = 1.5 + Math.sin(t * 2) * 0.3;
  toxicLight.intensity = 0.8 + Math.cos(t * 1.7) * 0.2;

  renderer.render(scene, camera);
}
