function getFieldCurves(m1Pos, m2Pos, m2Rot, isAttracting) {
  const curves = [];
  const offsets = [-0.35, -0.2, -0.05, 0.05, 0.2, 0.35];

  if(isAttracting) {
    offsets.forEach((yOffset, i) => {
      const start = new THREE.Vector3(m1Pos.x, m1Pos.y + yOffset * 0.6, m1Pos.z - 1.2);
      const end = new THREE.Vector3(m2Pos.x, m2Pos.y + yOffset * 0.6, m2Pos.z + 1.2);
      const mid1 = new THREE.Vector3(
        m1Pos.x + 0.3 + i * 0.1,
        m1Pos.y + yOffset * 0.6 + 0.4 + Math.abs(yOffset) * 0.3,
        m1Pos.z
      );
      const mid2 = new THREE.Vector3(
        m2Pos.x - 0.3 - i * 0.1,
        m2Pos.y + yOffset * 0.6 + 0.4 + Math.abs(yOffset) * 0.3,
        m2Pos.z
      );
      curves.push(new THREE.CatmullRomCurve3([start, mid1, mid2, end]));
    });

    offsets.forEach((yOffset, i) => {
      const start = new THREE.Vector3(m2Pos.x, m2Pos.y + yOffset * 0.6, m2Pos.z - 1.2);
      const end = new THREE.Vector3(m1Pos.x, m1Pos.y + yOffset * 0.6, m1Pos.z + 1.2);
      const mid1 = new THREE.Vector3(
        m2Pos.x - 0.3 - i * 0.1,
        m2Pos.y + yOffset * 0.6 - 0.6 - Math.abs(yOffset) * 0.4,
        m2Pos.z
      );
      const mid2 = new THREE.Vector3(
        m1Pos.x + 0.3 + i * 0.1,
        m1Pos.y + yOffset * 0.6 - 0.6 - Math.abs(yOffset) * 0.4,
        m1Pos.z
      );
      curves.push(new THREE.CatmullRomCurve3([start, mid1, mid2, end]));
    });
  } else {
    offsets.forEach((yOffset, i) => {
      const start = new THREE.Vector3(m1Pos.x, m1Pos.y + yOffset * 0.6, m1Pos.z - 1.2);
      const end = new THREE.Vector3(m2Pos.x, m2Pos.y + yOffset * 0.6, m2Pos.z - 1.2);
      const bend = Math.abs(m2Pos.x - m1Pos.x) * 0.8 + 1.5 + Math.abs(yOffset);
      const mid1 = new THREE.Vector3(
        m1Pos.x + 0.5,
        m1Pos.y + yOffset * 0.6 + 0.2,
        m1Pos.z - bend
      );
      const mid2 = new THREE.Vector3(
        m2Pos.x - 0.5,
        m2Pos.y + yOffset * 0.6 + 0.2,
        m2Pos.z - bend
      );
      curves.push(new THREE.CatmullRomCurve3([start, mid1, mid2, end]));
    });
  }

  return curves;
}

function updateFieldVisualization(curves, intensity, isAttracting) {
  while(fieldGroup.children.length > 0) {
    fieldGroup.remove(fieldGroup.children[0]);
  }

  const color = isAttracting ? 0x4488ff : 0xff4444;
  const emissive = isAttracting ? 0x2244aa : 0xaa2222;

  curves.forEach((curve, idx) => {
    const tubeRadius = 0.012 * (1 - Math.abs(idx - 5) * 0.08) * intensity;
    const geometry = new THREE.TubeGeometry(curve, 48, tubeRadius, 8, false);
    const material = fieldMaterialBase.clone();
    material.color.setHex(color);
    material.emissive.setHex(emissive);
    material.opacity = 0.4 * intensity * (1 - Math.abs(idx - 5) * 0.1);
    material.emissiveIntensity = 0.5 * intensity;

    const mesh = new THREE.Mesh(geometry, material);
    fieldGroup.add(mesh);
  });
}

let time = 0;
let currentCurves = [];

camera.position.set(0, 3.5, 7);
camera.lookAt(0, 0, 0);

function animate() {
  requestAnimationFrame(animate);
  const delta = clock.getDelta();
  time += delta;

  const cycleDuration = 10;
  const phase = (time % cycleDuration) / cycleDuration;
  const isAttracting = phase < 0.5;
  const transition = Math.sin((isAttracting ? phase : phase - 0.5) * Math.PI * 2) * 0.5 + 0.5;

  const minDist = 1.2;
  const maxDist = 4.5;
  const currentDist = isAttracting ? 
    minDist + (1 - transition) * (maxDist - minDist) * 0.3 :
    minDist + transition * (maxDist - minDist);

  magnet1.position.x = -currentDist / 2;
  magnet2.position.x = currentDist / 2;

  const targetRotation = isAttracting ? 0 : Math.PI;
  magnet2.rotation.y += (targetRotation - magnet2.rotation.y) * delta * 1.5;

  magnet1.position.y = Math.sin(time * 0.8) * 0.08;
  magnet2.position.y = Math.sin(time * 0.8 + 1) * 0.08;

  currentCurves = getFieldCurves(magnet1.position, magnet2.position, magnet2.rotation, isAttracting);
  const fieldIntensity = isAttracting ? 1.2 : 0.6 + (1 - transition) * 0.4;
  updateFieldVisualization(currentCurves, fieldIntensity, isAttracting);

  particles.forEach(p => {
    if(p.lineIndex < currentCurves.length) {
      const curve = currentCurves[p.lineIndex];
      p.progress += p.speed * delta * (isAttracting ? 1.2 : 0.6);
      if(p.progress > 1) p.progress = 0;

      const pos = curve.getPoint(p.progress);
      p.mesh.position.copy(pos);
      p.mesh.position.y += p.offset * (1 - Math.sin(p.progress * Math.PI)) * 0.2;

      const scale = 0.5 + Math.sin(p.progress * Math.PI) * 0.8;
      p.mesh.scale.setScalar(scale * (isAttracting ? 1 : 0.7));
      p.mesh.material.opacity = isAttracting ? 0.9 : 0.5;
      p.mesh.visible = true;
    } else {
      p.mesh.visible = false;
    }
  });

  rimLight.intensity = 0.35 + Math.sin(time * 1.2) * 0.08;

  controls.update();
  renderer.render(scene, camera);
}

